class Solution:
    def numSquares(self, n):
        dp = [0] + [n] * n                  # n ones always works
        k = 1
        while k * k <= n:
            sq = k * k
            for a in range(sq, n + 1):
                if dp[a - sq] + 1 < dp[a]:
                    dp[a] = dp[a - sq] + 1
            k += 1
        return dp[n]

