class Solution:
    def findNumberOfLIS(self, nums):
        n = len(nums)
        length = [1] * n        # longest increasing subsequence ending at i
        count = [1] * n         # how many of that length end at i
        for i in range(n):
            x = nums[i]
            li, ci = 1, 1
            for j in range(i):
                if nums[j] < x:
                    lj = length[j] + 1
                    if lj > li:
                        li, ci = lj, count[j]
                    elif lj == li:
                        ci += count[j]
            length[i], count[i] = li, ci
        best = max(length)
        return sum(c for l, c in zip(length, count) if l == best)

