class Solution:
    def uniquePathsWithObstacles(self, obstacleGrid):
        n = len(obstacleGrid[0])
        ways = [0] * n
        ways[0] = 1
        for row in obstacleGrid:
            for c in range(n):
                if row[c] == 1:
                    ways[c] = 0                  # nothing can pass through an obstacle
                elif c > 0:
                    ways[c] += ways[c - 1]       # from above (old value) + from the left
