class Solution:
    def minFallingPathSum(self, matrix):
        n = len(matrix)
        prev = list(matrix[0])                     # best sum of a path ending at each column
        for r in range(1, n):
            row = matrix[r]
            cur = [0] * n
            for c in range(n):
                m = prev[c]
                if c > 0 and prev[c - 1] < m:
                    m = prev[c - 1]
                if c + 1 < n and prev[c + 1] < m:
                    m = prev[c + 1]
                cur[c] = row[c] + m
            prev = cur
        return min(prev)

