minimum-ascii-delete-sum-for-two-strings.solution:
class Solution:
    def minimumDeleteSum(self, s1, s2):
        m = len(s2)
        b = [ord(ch) for ch in s2]
        prev = [0] * (m + 1)
        for j in range(m):
            prev[j + 1] = prev[j] + b[j]          # delete all of s2[:j+1]
        for ch in s1:
            a = ord(ch)
            cur = [prev[0] + a] + [0] * m
            for j in range(m):
                if a == b[j]:
                    cur[j + 1] = prev[j]
                else:
                    x, y = prev[j + 1] + a, cur[j] + b[j]
                    cur[j + 1] = x if x < y else y
            prev = cur
        return prev[m]

