last-stone-weight-ii.solution:
class Solution:
    def lastStoneWeightII(self, stones):
        total = sum(stones)
        half = total // 2
        reach = [True] + [False] * half          # reach[s]: some group of stones weighs exactly s
        for w in stones:
            for s in range(half, w - 1, -1):
                if reach[s - w]:
                    reach[s] = True
        best = max(s for s in range(half + 1) if reach[s])
        return total - 2 * best

